var st = HIGH, changedAt = -100, downAt = 0, a = 0, b = 0;

function setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, OUTPUT);
  pinMode(4, OUTPUT);
}

function loop() {
  var now = millis(), r = digitalRead(2);
  if (r !== st && now - changedAt > 40) {
    st = r; changedAt = now;
    if (r === LOW) downAt = now;
    else if (now - downAt < 500) a = !a; else b = !b;
  }
  digitalWrite(3, a);
  digitalWrite(4, b);
  delay(1);
}
